def _persist_review_verify_artifact(
    *,
    config: Config,
    store: SqliteTaskStore,
    task: DbTask,
    output: str,
    status: str,
    exit_status: str,
    tree_fingerprint: str,
) -> None:
    stored = store_command_output_artifact(
        store,
        task,
        config,
        kind="verify_command_output",
        producer="test",
        label="verify_command",
        output=output,
        status=status,
        exit_status=exit_status,
        head_sha=task.review_verify_head_sha,
        metadata={"tree_fingerprint": tree_fingerprint},
        created_at=task.review_verify_captured_at,
    )
    task.review_verify_artifact_file = stored.path
    store.update(task)


def _add_verify_only_noop_review_clearance_artifact(
    store: SqliteTaskStore,
    *,
    impl: DbTask,
    review: DbTask,
    source_task: DbTask,
    reviewed_head_sha: str,
    created_at: datetime,
    clearance_status: str = VERIFY_ONLY_NOOP_REVIEW_CLEARANCE_STATUS,
) -> None:
    assert impl.id is not None
    assert review.id is not None
    assert source_task.id is not None
    store.add_artifact(
        impl.id,
        kind=REVIEW_CLEARANCE_ARTIFACT_KIND,
        producer="test",
        label="review_clearance",
        path=f".gza/artifacts/{impl.id}/review_clearance.json",
        content_type="application/json; charset=utf-8",
        byte_size=2,
        sha256="0" * 64,
        created_at=created_at,
        status=clearance_status,
        head_sha=reviewed_head_sha,
        metadata={
            "clearance_kind": VERIFY_ONLY_NOOP_REVIEW_CLEARANCE_KIND,
            "clearance_status": clearance_status,
            "review_task_id": review.id,
            "source_task_id": source_task.id,
            "noop_improve_kind": NOOP_IMPROVE_KIND_VERIFY_ONLY,
            "reviewed_head_sha": reviewed_head_sha,
        },
    )


def _add_verify_only_noop_recovery_attention_artifact(
    store: SqliteTaskStore,
    *,
    review: DbTask,
    source_task: DbTask,
    reviewed_head_sha: str,
    created_at: datetime,
    message: str,
) -> None:
    assert review.id is not None
    assert source_task.id is not None
    store.add_artifact(
        source_task.id,
        kind=VERIFY_ONLY_NOOP_RECOVERY_ATTENTION_ARTIFACT_KIND,
        producer="test",
        label="verify_only_noop_recovery_attention",
        path=f".gza/artifacts/{source_task.id}/verify_only_noop_recovery_attention.txt",
        content_type="text/plain; charset=utf-8",
        byte_size=len(message.encode("utf-8")),
        sha256="1" * 64,
        created_at=created_at,
        status=VERIFY_ONLY_NOOP_RECOVERY_ATTENTION_STATUS,
        head_sha=reviewed_head_sha,
        metadata={
            "schema_version": 1,
            "attention_reason": "improve-no-op",
            "review_task_id": review.id,
            "source_task_id": source_task.id,
            "noop_improve_kind": NOOP_IMPROVE_KIND_VERIFY_ONLY,
            "reviewed_head_sha": reviewed_head_sha,
            "message": message,
        },
    )


def _add_review_blocker_resolution_artifact(
    store: SqliteTaskStore,
    *,
    review: DbTask,
    impl: DbTask,
    source_task: DbTask,
    finding_id: str,
    state: str,
    created_at: datetime,
    reason: str = "already_satisfied",
    evidence: str = "The guard already exists on the current branch tip.",
    current_state_citation: str = "`src/api.py:12-18`",
    fingerprint_title: str = "missing api guard",
    fingerprint_anchor: str = "src/api.py:12-18",
    dispute_source_task_id: str | None = None,
    disputed_artifact_id: int | None = None,
    head_sha: str | None = None,
):
    from gza.runner import REVIEW_BLOCKER_RESOLUTION_ARTIFACT_KIND

    assert review.id is not None
    assert impl.id is not None
    assert source_task.id is not None
    metadata: dict[str, object] = {
        "schema_version": 1,
        "state": state,
        "review_task_id": review.id,
        "impl_task_id": impl.id,
        "source_task_id": source_task.id,
        "source_task_type": source_task.task_type,
        "finding_id": finding_id,
        "reason": reason,
        "evidence": evidence,
        "current_state_citation": current_state_citation,
        "finding_fingerprint": {
            "title": fingerprint_title,
            "anchor": fingerprint_anchor,
        },
    }
    if dispute_source_task_id is not None:
        metadata["dispute_source_task_id"] = dispute_source_task_id
    if disputed_artifact_id is not None:
        metadata["disputed_artifact_id"] = disputed_artifact_id
    if head_sha is not None:
        metadata["head_sha"] = head_sha

    return store.add_artifact(
        review.id,
        kind=REVIEW_BLOCKER_RESOLUTION_ARTIFACT_KIND,
        label=f"{state}-{finding_id}",
        path=f".gza/artifacts/{state.lower()}-{finding_id.lower()}.txt",
        byte_size=0,
        sha256=("0" if state == "disputed" else "1") * 64,
        status=state,
        exit_status=reason,
        head_sha=head_sha,
        metadata=metadata,
        created_at=created_at,
    )


def _add_completed_rebase(
    store: SqliteTaskStore,
    impl: DbTask,
    *,
    when: datetime,
    changed_diff: bool | None = True,
) -> DbTask:
    assert impl.id is not None
    rebase = store.add(
        "Completed rebase",
        task_type="rebase",
        based_on=impl.id,
        same_branch=True,
    )
    assert rebase.id is not None
    rebase.status = "completed"
    rebase.completed_at = when
    rebase.branch = impl.branch
    rebase.has_commits = True
    rebase.changed_diff = changed_diff
    store.update(rebase)
    return rebase


def _add_rebase_diff_provenance(
    store: SqliteTaskStore,
    rebase: DbTask,
    *,
    resolved_head_sha: str = "rebased-sha",
    resolved_target_sha: str = "target-sha",
    target_at_start: str = "target-sha",
    changed_diff_boundary_proven: bool = True,
) -> DbTask:
    rebase.review_scope = build_rebase_diff_provenance(
        baseline=RebaseDiffBaseline(
            old_tip="pre-rebase-head",
            target_at_start=target_at_start,
            merge_base_at_start="pre-rebase-merge-base",
        ),
        resolved_head_sha=resolved_head_sha,
        resolved_target_sha=resolved_target_sha,
        changed_diff_boundary_proven=changed_diff_boundary_proven,
    )
    store.update(rebase)
    return rebase


def _resolution_review_scope_for(
    impl: DbTask,
    rebase: DbTask,
    *,
    resolved_head_sha: str = "rebased-sha",
    resolved_target_sha: str = "target-sha",
) -> str:
    assert impl.id is not None
    assert rebase.id is not None
    return build_resolution_review_scope(
        implementation_task_id=impl.id,
        rebase_task_id=rebase.id,
        resolved_head_sha=resolved_head_sha,
        resolved_target_sha=resolved_target_sha,
    )


def _assert_resolution_review_scope_matches_context(
    scope_text: str | None,
    *,
    impl: DbTask,
    rebase: DbTask,
    resolved_head_sha: str = "rebased-sha",
    resolved_target_sha: str = "target-sha",
) -> None:
    parsed = parse_resolution_review_scope(scope_text)
    assert parsed is not None
    assert parsed.implementation_task_id == impl.id
    assert parsed.rebase_task_id == rebase.id
    assert parsed.resolved_head_sha == resolved_head_sha
    assert parsed.resolved_target_sha == resolved_target_sha


def _make_failed_owner_with_completed_resume_descendant(
    store: SqliteTaskStore,
    *,
    branch: str,
    failed_at: datetime,
    resumed_at: datetime,
) -> tuple[DbTask, DbTask]:
    owner = store.add("Original implement", task_type="implement")
    assert owner.id is not None
    owner.status = "failed"
    owner.failure_reason = "MAX_STEPS"
    owner.completed_at = failed_at
    owner.branch = branch
    owner.merge_status = "unmerged"
    owner.has_commits = True
    store.update(owner)
    store.get_or_create_merge_unit_for_task(owner)

    resumed = store.add("Resumed implement", task_type="implement", based_on=owner.id)
    assert resumed.id is not None
    resumed.status = "completed"
    resumed.completed_at = resumed_at
    resumed.branch = branch
    resumed.merge_status = "unmerged"
    resumed.has_commits = True
    store.update(resumed)
    store.get_or_create_merge_unit_for_task(resumed)
    return owner, resumed


def _add_failed_rebase_attempts(
    store: SqliteTaskStore,
    impl: DbTask,
    *,
    hours: tuple[int, ...],
) -> list[DbTask]:
    assert impl.id is not None
    failed_rebases: list[DbTask] = []
    for hour in hours:
        failed_rebase = store.add(
            f"Failed rebase {hour}",
            task_type="rebase",
            based_on=impl.id,
            same_branch=True,
        )
        assert failed_rebase.id is not None
        failed_rebase.status = "failed"
        failed_rebase.completed_at = datetime(2026, 5, 14, hour, 0, tzinfo=UTC)
        failed_rebase.branch = impl.branch
        failed_rebase.failure_reason = "GIT_ERROR"
        store.update(failed_rebase)
        failed_rebases.append(failed_rebase)
    return failed_rebases


def _blocker_report(
    title: str,
    *,
    citation: str | None = "src/gza/foo.py:10",
    fix: str | None = "Fix it",
) -> ParsedReviewReport:
    return ParsedReviewReport(
        verdict="CHANGES_REQUESTED",
        findings=(
            ReviewFinding(
                id="B1",
                severity="BLOCKER",
                title=title,
                body="body",
                evidence=None,
                impact=None,
                fix_or_followup=fix,
                tests=None,
                open_state_citation=citation,
            ),
        ),
        format_version="v2",
    )


def _review_finding(finding_id: str, severity: str) -> ReviewFinding:
    return ReviewFinding(
        id=finding_id,
        severity=severity,  # type: ignore[arg-type]
        title=f"{finding_id} title",
        body="body",
        evidence="evidence",
        impact="impact",
        fix_or_followup="fix",
        tests="tests",
        open_state_citation="src/gza/example.py:1",
    )


def _review_output_with_findings(
    verdict: str,
    *,
    blockers: tuple[str, ...] = (),
    followups: tuple[str, ...] = (),
) -> str:
    sections = ["## Review", "", f"Verdict: {verdict}", ""]
    if blockers:
        sections.extend(["## Blockers", ""])
        for finding_id in blockers:
            sections.extend(
                [
                    f"### {finding_id} {finding_id} title",
                    "Evidence: evidence",
                    "Impact: impact",
                    "Required fix: fix",
                    "Required tests: tests",
                    "Open-state citation: src/gza/example.py:1",
                    "",
                ]
            )
    if followups:
        sections.extend(["## Follow-Ups", ""])
        for finding_id in followups:
            sections.extend(
                [
                    f"### {finding_id} {finding_id} title",
                    "Evidence: evidence",
                    "Impact: impact",
                    "Follow-up: fix",
                    "Required tests: tests",
                    "Open-state citation: src/gza/example.py:1",
                    "",
                ]
            )
    return "\n".join(sections)


def _persist_test_merge_finalization_proof(
    store: SqliteTaskStore,
    *,
    action_family: str,
    impl: DbTask,
    review: DbTask,
    findings: tuple[ReviewFinding, ...],
    children: tuple[DbTask, ...],
    target_sha: str = "same-sha",
    previous_target_sha: str = "previous-sha",
    target_branch: str = "main",
) -> None:
    assert impl.id is not None
    assert impl.branch is not None
    assert review.id is not None
    unit = store.resolve_merge_unit_for_task(impl.id)
    persist_merge_finalization_attempt_proof(
        store,
        action_family=action_family,  # type: ignore[arg-type]
        impl_task_id=impl.id,
        review_task_id=review.id,
        finding_ids=tuple(finding.id for finding in findings),
        child_task_ids=tuple(child.id for child in children if child.id is not None),
        source_branch=impl.branch,
        source_ref=impl.branch,
        source_ref_sha="source-sha",
        target_branch=target_branch,
        previous_target_sha=previous_target_sha,
        promoted_target_sha=target_sha,
        merge_unit_id=unit.id if unit is not None else None,
    )


def _persist_test_merge_finalization_prepared_attempt(
    store: SqliteTaskStore,
    *,
    action_family: str,
    impl: DbTask,
    review: DbTask,
    findings: tuple[ReviewFinding, ...],
    children: tuple[DbTask, ...],
    previous_target_sha: str = "target-before",
    target_branch: str = "main",
    promotion_observed: bool = False,
) -> None:
    assert impl.id is not None
    assert impl.branch is not None
    assert review.id is not None
    unit = store.resolve_merge_unit_for_task(impl.id)
    persist_merge_finalization_prepared_attempt(
        store,
        action_family=action_family,  # type: ignore[arg-type]
        impl_task_id=impl.id,
        review_task_id=review.id,
        finding_ids=tuple(finding.id for finding in findings),
        child_task_ids=tuple(child.id for child in children if child.id is not None),
        source_branch=impl.branch,
        source_ref=impl.branch,
        source_ref_sha="source-sha",
        target_branch=target_branch,
        previous_target_sha=previous_target_sha,
        merge_unit_id=unit.id if unit is not None else None,
        promotion_observed=promotion_observed,
    )


