def _persist_verify_artifact(
    tmp_path: Path,
    *,
    relative_path: str,
    content: str,
) -> str:
    artifact_path = tmp_path / relative_path
    artifact_path.parent.mkdir(parents=True, exist_ok=True)
    artifact_path.write_text(content, encoding="utf-8")
    return relative_path


