@pytest.mark.parametrize(
    ("closing_review_status", "expected_action_type"),
    [
        ("pending", "run_review"),
        ("in_progress", "wait_review"),
        ("completed", None),
        # A failed closing review must NOT satisfy the invariant — it blocks merge
        # and routes to recovery (create_review retry) rather than returning None.
        ("failed", "create_review"),
    ],
)
def test_closing_review_invariant_does_not_create_duplicate_review(
    tmp_path: Path,
    closing_review_status: str,
    expected_action_type: str | None,
) -> None:
    store = _make_store(tmp_path)

    impl = store.add("Implement feature", task_type="implement")
    assert impl.id is not None
    impl.status = "completed"
    impl.completed_at = datetime(2026, 1, 1, tzinfo=UTC)
    impl.branch = "feat/closing-review-dedupe"
    impl.merge_status = "unmerged"
    impl.has_commits = True
    store.update(impl)

    stale_review = store.add("Old review", task_type="review", depends_on=impl.id)
    assert stale_review.id is not None
    stale_review.status = "completed"
    stale_review.completed_at = datetime(2026, 1, 2, tzinfo=UTC)
    store.update(stale_review)

    improve = store.add(
        "Improve feature",
        task_type="improve",
        based_on=impl.id,
        depends_on=stale_review.id,
        same_branch=True,
    )
    assert improve.id is not None
    improve.status = "completed"
    improve.completed_at = datetime(2026, 1, 3, tzinfo=UTC)
    store.update(improve)

    impl.review_cleared_at = datetime(2026, 1, 3, tzinfo=UTC)
    store.update(impl)

    closing_review = store.add("Closing review", task_type="review", depends_on=impl.id)
    assert closing_review.id is not None
    closing_review.status = closing_review_status
    closing_review.created_at = datetime(2026, 1, 4, tzinfo=UTC)
    if closing_review_status in {"completed", "failed"}:
        closing_review.completed_at = datetime(2026, 1, 4, tzinfo=UTC)
    store.update(closing_review)

    action = resolve_closing_review_action(
        task=impl,
        reviews=store.get_reviews_for_task(impl.id),
        latest_completed_review=stale_review,
        latest_completed_code_change=improve,
    )

    if expected_action_type is None:
        assert action is None
    else:
        assert action is not None
        assert action["type"] == expected_action_type
        # run_review / wait_review carry a review_task reference; create_review does not
        if expected_action_type in {"run_review", "wait_review"}:
            assert action.get("review_task").id == closing_review.id


def test_failed_closing_review_blocks_merge_and_routes_to_retry(
    tmp_path: Path,
    monkeypatch,
) -> None:
    """Regression: review_cleared=True + failed closing review must NOT produce a merge action.

    Reproduces the gza-4073 shape: stale CHANGES_REQUESTED verdict + review_cleared_at
    set by a completed improve + a FAILED follow-on closing review.  Before the fix,
    closing_review_action returned None (invariant 'satisfied') and has_valid_review_for_merge
    returned True via the review_cleared branch, causing auto-merge.
    """
    from gza import advance_engine as advance_engine_module

    store = _make_store(tmp_path)
    config = Config.load(tmp_path)

    impl = _make_completed_unmerged_impl(
        store,
        branch="feat/failed-closing-review-no-merge",
        when=datetime(2026, 5, 1, 9, 0, tzinfo=UTC),
    )

    # Stale CHANGES_REQUESTED review (before the improve)
    stale_review = _add_completed_review(store, impl, when=datetime(2026, 5, 1, 10, 0, tzinfo=UTC))
    monkeypatch.setattr(
        advance_engine_module,
        "get_review_report",
        lambda project_dir, r: ParsedReviewReport(
            verdict="CHANGES_REQUESTED",
            findings=(),
            format_version="legacy",
        ),
    )

    # Improve clears the review state
    improve = _add_completed_improve_for_review(
        store, impl, stale_review, when=datetime(2026, 5, 1, 11, 0, tzinfo=UTC)
    )
    impl.review_cleared_at = improve.completed_at
    store.update(impl)

    # Closing review fails (e.g., 429 Too Many Requests)
    closing_review = store.add("Closing review", task_type="review", depends_on=impl.id)
    assert closing_review.id is not None
    closing_review.status = "failed"
    closing_review.failure_reason = "429 Too Many Requests"
    closing_review.created_at = datetime(2026, 5, 1, 12, 0, tzinfo=UTC)
    closing_review.completed_at = datetime(2026, 5, 1, 12, 30, tzinfo=UTC)
    store.update(closing_review)

    action = evaluate_advance_rules(config, store, _FakeGit(can_merge=True), impl, "main")

    # Must NOT merge — must retry the closing review
    assert action["type"] != "merge", f"Expected retry action but got merge: {action}"
    assert action["type"] == "verify_gate", action
    assert action["verify_gate_phase"] == "pre_review"
    assert action["description"] == "Run verify gate before review"


def test_completed_recovered_closing_review_counts_as_review_evidence(
    tmp_path: Path,
    monkeypatch,
) -> None:
    """Automatic review recovery descendants count; manual merge-unit follow-ups do not."""
    from gza import advance_engine as advance_engine_module

    store = _make_store(tmp_path)
    config = Config.load(tmp_path)

    impl = _make_completed_unmerged_impl(
        store,
        branch="feat/recovered-closing-review",
        when=datetime(2026, 5, 2, 9, 0, tzinfo=UTC),
    )
    assert store.get_or_create_merge_unit_for_task(impl) is not None
    stale_review = _add_completed_review(store, impl, when=datetime(2026, 5, 2, 10, 0, tzinfo=UTC))
    improve = _add_completed_improve_for_review(
        store,
        impl,
        stale_review,
        when=datetime(2026, 5, 2, 11, 0, tzinfo=UTC),
    )

    failed_closing = store.add(
        "Closing review",
        task_type="review",
        based_on=impl.id,
        depends_on=impl.id,
    )
    assert failed_closing.id is not None
    failed_closing.status = "failed"
    failed_closing.completed_at = datetime(2026, 5, 2, 12, 0, tzinfo=UTC)
    store.update(failed_closing)

    recovered_completed_review = store.add(
        failed_closing.prompt,
        task_type="review",
        based_on=failed_closing.id,
        depends_on=failed_closing.depends_on,
        recovery_origin="retry",
    )
    assert recovered_completed_review.id is not None
    recovered_completed_review.status = "completed"
    recovered_completed_review.completed_at = datetime(2026, 5, 2, 13, 0, tzinfo=UTC)
    recovered_completed_review.report_file = f"reviews/{recovered_completed_review.id}.md"
    store.update(recovered_completed_review)
    assert store.get_or_create_merge_unit_for_task(recovered_completed_review) is not None

    manual_followup = store.add(
        "Manual review follow-up",
        task_type="review",
        based_on=failed_closing.id,
        depends_on=failed_closing.depends_on,
        recovery_origin="manual",
    )
    assert manual_followup.id is not None
    manual_followup.status = "completed"
    manual_followup.completed_at = datetime(2026, 5, 2, 14, 0, tzinfo=UTC)
    manual_followup.report_file = f"reviews/{manual_followup.id}.md"
    store.update(manual_followup)
    assert store.get_or_create_merge_unit_for_task(manual_followup) is not None

    impl_merge_unit = store.resolve_merge_unit_for_task(impl.id)
    recovered_merge_unit = store.resolve_merge_unit_for_task(recovered_completed_review.id)
    manual_merge_unit = store.resolve_merge_unit_for_task(manual_followup.id)
    assert impl_merge_unit is not None
    assert recovered_merge_unit is not None
    assert manual_merge_unit is not None
    assert recovered_merge_unit.id == impl_merge_unit.id
    assert manual_merge_unit.id == impl_merge_unit.id

    review_evidence = get_implementation_review_evidence(store, impl)
    evidence_ids = [review.id for review in review_evidence]
    assert recovered_completed_review.id in evidence_ids
    assert manual_followup.id not in evidence_ids

    monkeypatch.setattr(
        advance_engine_module,
        "get_review_report",
        lambda project_dir, review: ParsedReviewReport(
            verdict="APPROVED" if review.id == recovered_completed_review.id else "CHANGES_REQUESTED",
            findings=(),
            format_version="legacy",
        ),
    )

    action = evaluate_advance_rules(config, store, _FakeGit(can_merge=True), impl, "main")

    assert action["type"] == "verify_gate", action
    assert action["verify_gate_phase"] == "pre_merge"
    assert action["type"] != "create_review"
    assert improve.id is not None
    assert action.get("closing_review_action") is None


def test_get_implementation_review_evidence_excludes_review_with_missing_review_parent(
    tmp_path: Path,
) -> None:
    """Malformed review-to-review ancestry must fail closed instead of becoming latest evidence."""
    store = _make_store(tmp_path)

    impl = _make_completed_unmerged_impl(
        store,
        branch="feat/malformed-review-parent",
        when=datetime(2026, 5, 3, 9, 0, tzinfo=UTC),
    )
    direct_review = _add_completed_review(store, impl, when=datetime(2026, 5, 3, 10, 0, tzinfo=UTC))

    malformed_recovered_review = store.add(
        "Malformed recovered review",
        task_type="review",
        based_on="gza-999999",
        depends_on=impl.id,
    )
    assert malformed_recovered_review.id is not None
    malformed_recovered_review.status = "completed"
    malformed_recovered_review.completed_at = datetime(2026, 5, 3, 11, 0, tzinfo=UTC)
    store.update(malformed_recovered_review)
